import Foundation
import SystemCore

/// The bundled library, decoded once from `library.json` (generated by `Scripts/build_library.py`).
public enum ExerciseLibrary {
    /// Bumped whenever entries are added or retagged.
    public static let version: Int = 2

    /// Every bundled entry in library order: strength work, then mobility drills, warm-ups,
    /// stretches and conditioning.
    public static let bundled: [Exercise] = load()

    public static let byID: [String: Exercise] = Dictionary(bundled.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })

    private static func load() -> [Exercise] {
        guard let url = Bundle.module.url(forResource: "library", withExtension: "json") else {
            assertionFailure("library.json is missing from the ExerciseLibrary bundle")
            return []
        }
        do {
            return try JSONDecoder().decode([Exercise].self, from: Data(contentsOf: url))
        } catch {
            assertionFailure("library.json failed to decode: \(error)")
            return []
        }
    }
}

/// Every exercise the person can use: the library, then their own. Lookups find the first entry
/// with an id, so a custom exercise can never shadow a library one.
public struct ExerciseCatalog: Sendable {
    public let all: [Exercise]
    private let index: [String: Exercise]

    public init(custom: [Exercise] = []) {
        self.init(exercises: ExerciseLibrary.bundled + custom)
    }

    public init(exercises: [Exercise]) {
        all = exercises
        index = Dictionary(exercises.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })
    }

    public subscript(id: String) -> Exercise? { index[id] }

    /// The exercise for an id, or a placeholder when it's no longer known, so history stays readable.
    public func resolve(_ id: String) -> Exercise { index[id] ?? .placeholder(id: id) }

    public func of(kind: ExerciseKind) -> [Exercise] { all.filter { $0.kind == kind } }
}

extension Exercise {
    /// Stands in for an unknown id: a name made from the id, no muscles or joints, a middling cost
    /// and the most cautious safety tier.
    public static func placeholder(id: String) -> Exercise {
        Exercise(
            id: id, name: id.replacingOccurrences(of: "-", with: " ").capitalized, pattern: .core, equipment: .bodyweight,
            muscles: [], joints: [], fatigue: FatigueProfile(systemic: 0.3, local: 0.4, stimulus: 0.7),
            safetyTier: .neverToFailure,
            reps: RepDefaults(strength: RepRange(8, 12), hypertrophy: RepRange(8, 12)),
            rest: RestDefaults(strength: 90, hypertrophy: 75))
    }
}
